import{_ as e,c as t,o as a,a2 as i}from"./chunks/framework.B3iQLowF.js";const n=JSON.parse('{"title":"Attestation SDK - Technical Architecture | Mohanpathi Portfolio","description":"Enterprise-grade software project by Mohanpathi - System Architect & Full-Stack Engineer","frontmatter":{"layout":"doc","title":"Attestation SDK - Technical Architecture"},"headers":[],"relativePath":"docs/attestify/tech-architecture.md","filePath":"docs/attestify/tech-architecture.md","lastUpdated":1741638736000}');const s=e({name:"docs/attestify/tech-architecture.md"},[["render",function(e,n,s,r,o,l){return a(),t("div",null,n[0]||(n[0]=[i('<h1 id="attestation-sdk" tabindex="-1">Attestation SDK <a class="header-anchor" href="#attestation-sdk" aria-label="Permalink to &quot;Attestation SDK&quot;">​</a></h1><p><strong>Technical Architecture</strong><br><em>Powering secure attestations with a robust, layered design</em></p><h2 id="technical-architecture" tabindex="-1">Technical Architecture <a class="header-anchor" href="#technical-architecture" aria-label="Permalink to &quot;Technical Architecture&quot;">​</a></h2><p>The <strong>Attestation SDK</strong> ecosystem is built to deliver secure, scalable, and developer-friendly attestation management. Its architecture spans three key layers: the <strong>Core SDK</strong> (TypeScript library), the <strong>Attestify Backend</strong> (Node.js service), and the <strong>Attestify CLI</strong> (command-line interface). Together, they form a cohesive system for handling digital payment commitments and mutual attestations, leveraging HD wallets, cryptographic signatures, and RESTful APIs.</p><p>Below, we break down each component and how they interconnect to power the Attestify experience.</p><hr><h2 id="core-sdk" tabindex="-1">Core SDK <a class="header-anchor" href="#core-sdk" aria-label="Permalink to &quot;Core SDK&quot;">​</a></h2><p>The foundation of Attestify, written in TypeScript, provides the logic for attestation lifecycle management and cryptographic operations.</p><h3 id="key-components" tabindex="-1">Key Components <a class="header-anchor" href="#key-components" aria-label="Permalink to &quot;Key Components&quot;">​</a></h3><ul><li><p><strong>Attestation Class</strong><br><em>Manages the attestation lifecycle</em></p><ul><li>Derives deterministic keys from extended public keys (xpubs) using BIP32/BIP39.</li><li>Tracks state transitions: Initiated → Acknowledged → Effective → Discharged.</li><li>Creates and verifies signatures with secure payload handling.</li><li>Generates unique attestation IDs with UUID v4.</li></ul></li><li><p><strong>SignatureService</strong><br><em>Handles cryptographic operations</em></p><ul><li>Hashes payloads using SHA-256.</li><li>Signs data with secp256k1 elliptic curve cryptography.</li><li>Verifies signatures against public keys.</li><li>Uses BN.js for big-number calculations.</li></ul></li></ul><h3 id="technical-stack" tabindex="-1">Technical Stack <a class="header-anchor" href="#technical-stack" aria-label="Permalink to &quot;Technical Stack&quot;">​</a></h3><ul><li><strong>tiny-secp256k1</strong>: Elliptic curve operations for signatures.</li><li><strong>bip32/bip39</strong>: HD wallet functionality.</li><li><strong>elliptic</strong>: Additional signature operations.</li><li><strong>UUID v4</strong>: Unique identifier generation.</li></ul><p>The Core SDK is lightweight yet powerful, designed to integrate seamlessly with external signing services (e.g., MetaMask, WalletConnect) and custom derivation paths (e.g., Ethereum’s <code>m/44&#39;/60&#39;/0&#39;/0</code>).</p><hr><h2 id="attestify-backend" tabindex="-1">Attestify Backend <a class="header-anchor" href="#attestify-backend" aria-label="Permalink to &quot;Attestify Backend&quot;">​</a></h2><p>A Node.js-based service that extends the Core SDK with persistent storage and API-driven workflows.</p><h3 id="architecture-diagram" tabindex="-1">Architecture Diagram <a class="header-anchor" href="#architecture-diagram" aria-label="Permalink to &quot;Architecture Diagram&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐     ┌─────────────┐     ┌────────────┐</span></span>\n<span class="line"><span>│    Client    │ ←─→ │   Express   │ ←─→ │  MongoDB   │</span></span>\n<span class="line"><span>│    (CLI)     │     │   Server    │     │ Database   │</span></span>\n<span class="line"><span>└──────────────┘     └─────────────┘     └────────────┘</span></span>\n<span class="line"><span>                           ↓</span></span>\n<span class="line"><span>                    ┌─────────────┐</span></span>\n<span class="line"><span>                    │  Attestify  │</span></span>\n<span class="line"><span>                    │    SDK      │</span></span>\n<span class="line"><span>                    └─────────────┘</span></span>\n<span class="line"><span>                           ↓</span></span>\n<span class="line"><span>                    ┌─────────────┐</span></span>\n<span class="line"><span>                    │ Crypto &amp; HD │</span></span>\n<span class="line"><span>                    │   Wallet    │</span></span>\n<span class="line"><span>                    └─────────────┘</span></span></code></pre></div><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>RESTful APIs</strong>: Endpoints for user management and commitment lifecycle (e.g., <code>/create-attestation</code>, <code>/acknowledge-attestation</code>).</li><li><strong>MongoDB Integration</strong>: Stores attestation data and user profiles.</li><li><strong>JWT Authentication</strong>: Secures API access with token-based auth.</li><li><strong>Signature Verification</strong>: Validates cryptographic signatures at each state transition.</li></ul><h3 id="technical-stack-1" tabindex="-1">Technical Stack <a class="header-anchor" href="#technical-stack-1" aria-label="Permalink to &quot;Technical Stack&quot;">​</a></h3><ul><li><strong>Node.js</strong>: Runtime environment.</li><li><strong>Express</strong>: Web framework for APIs.</li><li><strong>MongoDB</strong>: NoSQL database for persistence.</li><li><strong>Core SDK</strong>: Embedded for attestation logic and crypto operations.</li></ul><p>The backend bridges the Core SDK’s functionality with real-world applications, ensuring data durability and secure access.</p><hr><h2 id="attestify-cli" tabindex="-1">Attestify CLI <a class="header-anchor" href="#attestify-cli" aria-label="Permalink to &quot;Attestify CLI&quot;">​</a></h2><p>A command-line tool that interacts with the backend, providing a user-friendly interface for attestation workflows.</p><h3 id="role-in-the-architecture" tabindex="-1">Role in the Architecture <a class="header-anchor" href="#role-in-the-architecture" aria-label="Permalink to &quot;Role in the Architecture&quot;">​</a></h3><ul><li><strong>Client Layer</strong>: Communicates with the backend via HTTPS/REST.</li><li><strong>Automation</strong>: Executes the full commitment lifecycle (e.g., <code>npm run lifecycle</code>).</li><li><strong>User Interaction</strong>: Simplifies tasks like registration, commitment creation, and state updates.</li></ul><h3 id="technical-stack-2" tabindex="-1">Technical Stack <a class="header-anchor" href="#technical-stack-2" aria-label="Permalink to &quot;Technical Stack&quot;">​</a></h3><ul><li><strong>Node.js</strong>: Powers the CLI runtime.</li><li><strong>Core SDK</strong>: Embedded for local cryptographic operations (e.g., mnemonic-based key derivation).</li><li><strong>HTTPS Client</strong>: Connects to the backend’s REST APIs.</li></ul><p>The CLI acts as both a testing tool and a practical interface, making attestation management accessible without a GUI.</p><hr><h2 id="how-it-all-fits-together" tabindex="-1">How It All Fits Together <a class="header-anchor" href="#how-it-all-fits-together" aria-label="Permalink to &quot;How It All Fits Together&quot;">​</a></h2><ol><li><strong>Core SDK</strong>: Provides the cryptographic and attestation logic, usable standalone or integrated into other systems.</li><li><strong>Backend</strong>: Wraps the SDK with a persistent layer, exposing APIs for broader application use.</li><li><strong>CLI</strong>: Ties it all together, offering a hands-on way to interact with the backend and test the SDK’s capabilities.</li></ol><p>This layered approach ensures flexibility—use the SDK alone for lightweight projects, or pair it with the backend and CLI for a full-featured attestation system.</p><hr><h2 id="security-foundations" tabindex="-1">Security Foundations <a class="header-anchor" href="#security-foundations" aria-label="Permalink to &quot;Security Foundations&quot;">​</a></h2><ul><li><strong>Cryptography</strong>: secp256k1 and SHA-256 ensure signature integrity.</li><li><strong>HD Wallets</strong>: BIP32/BIP39 provide secure, hierarchical key management.</li><li><strong>State Validation</strong>: Enforces valid transitions with signature checks.</li><li><strong>Backend Security</strong>: JWT, bcrypt hashing, and input validation protect the API.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Explore the <a href="./usecases">Use Cases</a> to see how this architecture solves real problems, or jump to <a href="./implementation">Implementation</a> for setup and code examples.</p>',41)]))}]]);export{n as __pageData,s as default};
